class Solution {
    public int[][] blackout(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] out = new int[m][];
        for (int r = 0; r < m; r++) out[r] = grid[r].clone();
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                if (grid[r][c] == 0) {
                    for (int k = 0; k < n; k++) out[r][k] = 0;
                    for (int k = 0; k < m; k++) out[k][c] = 0;
                }
        return out;
    }
}

