        m, n = len(grid), len(grid[0])
        zero_row, zero_col = [False] * m, [False] * n
        for r in range(m):
            for c in range(n):
                if grid[r][c] == 0:
                    zero_row[r] = zero_col[c] = True
        for r in range(m):
            for c in range(n):
                if zero_row[r] or zero_col[c]:
                    grid[r][c] = 0
        return grid

