class Solution:
    def blackout(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        row0 = any(grid[0][c] == 0 for c in range(n))
        col0 = any(grid[r][0] == 0 for r in range(m))
        for r in range(1, m):
            for c in range(1, n):
                if grid[r][c] == 0:
                    grid[r][0] = grid[0][c] = 0
        for r in range(1, m):
            for c in range(1, n):
                if grid[r][0] == 0 or grid[0][c] == 0:
                    grid[r][c] = 0
        if row0:
            for c in range(n):
                grid[0][c] = 0
        if col0:
            for r in range(m):
                grid[r][0] = 0
        return grid

