class Solution {
    public int[][] blackout(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean row0 = false, col0 = false;
        for (int c = 0; c < n; c++) if (grid[0][c] == 0) row0 = true;
        for (int r = 0; r < m; r++) if (grid[r][0] == 0) col0 = true;
        for (int r = 1; r < m; r++)
            for (int c = 1; c < n; c++)
                if (grid[r][c] == 0) grid[r][0] = grid[0][c] = 0;
        for (int r = 1; r < m; r++)
            for (int c = 1; c < n; c++)
                if (grid[r][0] == 0 || grid[0][c] == 0) grid[r][c] = 0;
        if (row0) for (int c = 0; c < n; c++) grid[0][c] = 0;
        if (col0) for (int r = 0; r < m; r++) grid[r][0] = 0;
        return grid;
    }
}

